using System;
using System.Collections.Generic;
using LittleLeo;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "HeveliusLinkEffect", menuName = "Data/Battle/Effects/Hevelius/HeveliusLink Effect")]
public class HeveliusLinkEffect : Effect
{
	private const string linkWhileSentinelActiveID = "LinkWhileSentinelActive";

	[Header("Possible Effects")]
	[SerializeField]
	private HeveliusHeveliusLinkEffect effect;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private bool stackableEffects;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	[Header("Corruption Increase")]
	[SerializeField]
	private bool increaseCorruptionReceived;

	[SerializeField]
	[ShowIf("increaseCorruptionReceived")]
	private Effect tormentEffect;

	[SerializeField]
	[ShowIf("increaseCorruptionReceived")]
	private bool enableIncreaseCorruptionReceivedFixedAmount;

	[SerializeField]
	[ShowIf("enableIncreaseCorruptionReceivedFixedAmount")]
	private int increaseCorruptionReceivedFixedAmount;

	[NonSerialized]
	public bool NoFeeback;

	public bool IncreaseCorruptionReceived => increaseCorruptionReceived;

	public bool EnableIncreaseCorruptionReceivedFixedAmount => enableIncreaseCorruptionReceivedFixedAmount;

	public int IncreaseCorruptionReceivedFixedAmount => increaseCorruptionReceivedFixedAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string whileThisSentinelIsActiveDescription = GetWhileThisSentinelIsActiveDescription();
		whileThisSentinelIsActiveDescription = ((amount != EffectsValues.NO_VALUE) ? Smart.Format(whileThisSentinelIsActiveDescription, amount, effect.HeveliusLinkEffect.GetEffectName()) : GetEffectDescriptionWithAmountReplacedWithX(whileThisSentinelIsActiveDescription, GetNumberToReplaceWithX(), effect.HeveliusLinkEffect.GetEffectName()));
		return whileThisSentinelIsActiveDescription + GetIncreaseCorruptionReceivedDescription(amount) + AppendedDescription();
	}

	protected string GetWhileThisSentinelIsActiveDescription()
	{
		return base.localizationManager.GetLocalizedString("LinkWhileSentinelActive");
	}

	protected string GetIncreaseCorruptionReceivedDescription(int amount)
	{
		if (increaseCorruptionReceived)
		{
			int amount2 = (enableIncreaseCorruptionReceivedFixedAmount ? increaseCorruptionReceivedFixedAmount : amount);
			return "\n" + tormentEffect.GetEffectDescription(amount2);
		}
		return "";
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		playerGameObjectReference.value.GetComponent<UnitEffects>().AddEffect(effect, effectAmount, !NoFeeback, callEffectsCallbacks: true, null, gainingEffectVFXAndSFX: false);
		CheckLinkDuplicateOmen(effectAmount, effectOwner, source);
		List<VFXHolder> vFXHolders = ReferenceSingleton<VFXHandler>.Instance.GetVFXHolders();
		for (int i = 0; i < vFXHolders.Count; i++)
		{
			VFXHolder vFXHolder = vFXHolders[i];
			if (vFXHolder.VFXOwner == effectOwner && vFXHolder.effectVFX is HeveliusLinkEffect)
			{
				return;
			}
		}
		if (IsVFXEnabled())
		{
			GameObject vFX = GetVFX(GetVFXOwnerPosition(effectOwner));
			ReferenceSingleton<VFXHandler>.Instance.AddToVFXHolders(new VFXHolder(effectOwner, this, vFX));
			vFX.GetComponent<ParticleEmissionController>().SetActive(value: true);
			int num = ((effectOwner.GetComponent<CompanionInitializer>().PositioningIndex == 0) ? (-170) : 10);
			vFX.transform.GetFirstChild().SetLocalEulerAnglesZ(num);
		}
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		int num = effectAmount;
		if (stackableEffects)
		{
			num = 0;
			for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
			{
				num += currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>().IsEffectActiveGetAmount(this, activateFeedback: false);
			}
		}
		UnitEffects component = playerGameObjectReference.value.GetComponent<UnitEffects>();
		int effectAmount2 = num - component.IsEffectActiveGetAmount(effect, activateFeedback: false);
		component.AddEffect(effect, effectAmount2, effectFeedback: true, callEffectsCallbacks: true, null, gainingEffectVFXAndSFX: false);
		CheckLinkDuplicateOmen(effectAmount2, effectOwner, source);
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		Debug.Log("HEVELIUS LINK: " + effect.name + " " + effectAmount);
		if (effectOwner.GetComponent<CompanionEffects>().IsLinksActiveGetAmount() == 0)
		{
			VFXHolder vFXInstanceFromVFXHoldersAndRemoveItFromList = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHoldersAndRemoveItFromList(effectOwner, this);
			if (vFXInstanceFromVFXHoldersAndRemoveItFromList != null)
			{
				GameObject vFXInstance = vFXInstanceFromVFXHoldersAndRemoveItFromList.VFXInstance;
				vFXInstance.GetComponent<ParticleEmissionController>().SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vFXInstance, 4f);
			}
		}
		if (base.HideEffectValue)
		{
			Debug.Log("HEVELIUS LINK HIDE EFFECT VALUE: " + effect.name + " " + effectAmount);
			for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
			{
				if (currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>().IsEffectActive(this))
				{
					return;
				}
			}
			playerGameObjectReference.value.GetComponent<UnitEffects>().RemoveEffect(effect);
		}
		else
		{
			playerGameObjectReference.value.GetComponent<UnitEffects>().DecreaseEffect(effect, effectAmount, !NoFeeback);
		}
	}

	private void CheckLinkDuplicateOmen(int effectAmount, GameObject effectOwner, GameObject source)
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.ActivateLinkDuplicateAction(this, effectAmount, effectOwner, source);
	}
}
